#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""ТІЛЬКИ ЧИТАННЯ. Прихід від клієнтів по рахунках за весь час + приклад ланцюжка."""
import collections, os, sys, urllib.parse
BASE = "/root/unitex-finrep"
sys.path.insert(0, os.path.join(BASE, "engine"))
os.chdir(BASE)
from odata_client import ODataClient
c = ODataClient()

def get(p): return c._get(urllib.parse.quote(p, safe="/?&=$,'"))
def page(ent, sel=None):
    out, skip = [], 0
    while True:
        p = "/%s?$format=json&$top=1000&$skip=%d" % (ent, skip)
        if sel: p += "&$select=" + ",".join(sel)
        b = get(p)["value"]; out += b
        if len(b) < 1000: return out
        skip += 1000
def d10(x):
    x = str(x or ""); return "" if (not x or x.startswith("0001-01-01")) else x[:10]
def f(x):
    try: return float(x or 0)
    except (TypeError, ValueError): return 0.0
def nm(e):
    return {r["Ref_Key"]: (r.get("Description") or "").strip()
            for r in page(e, ["Ref_Key", "Description"])}
def blank(x): return (not x) or str(x).startswith("00000000-0000")

acc = nm("Catalog_ВидОплаты"); cur = nm("Catalog_Валюты"); ctr = nm("Catalog_Контрагенты")
art = nm("Catalog_СтатьиСчета")
deal = {r["Ref_Key"]: (r.get("Number") or "").lstrip("0")
        for r in page("Document_Сделка", ["Ref_Key", "Number"])}

pr = [r for r in page("Document_Приход") if r.get("Posted") and not r.get("DeletionMark")]
print("=== ПРИХІД ВІД КЛІЄНТІВ ЗА ВЕСЬ ЧАС (%d док.) ===" % len(pr))
g = collections.Counter(); s = collections.Counter(); first = {}; last = {}
for r in pr:
    a = acc.get(r.get("ВидОплаты_Key"), "?") or "(порожньо)"
    g[a] += 1; s[a] += f(r.get("Сумма_УЕ"))
    d = d10(r.get("Date"))
    if d:
        first[a] = min(first.get(a, "9999"), d); last[a] = max(last.get(a, ""), d)
for a, n in g.most_common():
    print("  %-30s %3d док.  %12.2f УО   %s … %s" % (a, n, s[a], first.get(a, "—"), last.get(a, "—")))

print("\n=== ЛАНЦЮЖОК на прикладі 27.08.2026 ===")
vp = [r for r in page("Document_ВнутреннееПеремещение")
      if r.get("Posted") and not r.get("DeletionMark") and d10(r.get("Date")) >= "2026-08-25"]
for r in sorted(vp, key=lambda x: d10(x.get("Date"))):
    print("  ПЕРЕМІЩЕННЯ №%-4s %s  %s (%s %s, курс %s) → %s (%s %s)  = %s УО"
          % ((r.get("Number") or "").lstrip("0"), d10(r.get("Date")),
             acc.get(r.get("ВидОплаты_Key"), "?"), r.get("Сумма_вал"),
             cur.get(r.get("Валюта_Key"), ""), r.get("Курс"),
             acc.get(r.get("ВидОплаты2_Key"), "?"), r.get("Сумма_вал2"),
             cur.get(r.get("Валюта2_Key"), ""), r.get("Сумма_УЕ")))

rn = {r["Ref_Key"]: r for r in page("Document_РасходнаяНакладная",
      ["Ref_Key", "Number", "Сделка_Key", "Услуга_Key", "Контрагент_Key"])}
lines = collections.defaultdict(list)
for r in page("Document_СписаниеДенСредств_Счета"):
    lines[r["Ref_Key"]].append(r)
print("\n=== ПЛАТЕЖІ З РАХУНКУ «Банк Cr String Cycle LLC» (куди пішла куплена валюта) ===")
sd = [r for r in page("Document_СписаниеДенСредств")
      if r.get("Posted") and not r.get("DeletionMark")
      and acc.get(r.get("ВидОплаты_Key"), "") == "Банк Cr String Cycle LLC"
      and d10(r.get("Date")) >= "2026-05-01"]
print("  документів з 01.05.26:", len(sd))
for h in sorted(sd, key=lambda x: d10(x.get("Date")))[-6:]:
    print("   №%-5s %s  отримувач %s  %s УО"
          % ((h.get("Number") or "").lstrip("0"), d10(h.get("Date")),
             (ctr.get(h.get("Контрагент_Key")) or "—")[:26], h.get("Сумма_УЕ")))
    for ln in lines.get(h["Ref_Key"], []):
        t = rn.get(ln.get("Счет"))
        if t:
            print("        → угода №%-5s  «%s»  %s УО"
                  % (deal.get(t.get("Сделка_Key"), "—"),
                     art.get(t.get("Услуга_Key"), "—"), ln.get("Сумма_УЕ")))
        else:
            print("        → накладні витрати  %s УО" % ln.get("Сумма_УЕ"))
PYEOF
